"""Build the assembled fan review page from its actual rendered timeline."""
from pathlib import Path
import json
from html import escape
D=Path(__file__).resolve().parent/'integrated'
s=json.loads((D/'shot.json').read_text())
cards=[]
for k,f in enumerate(s['keys'],1):
 t=s['frames'][f]['source_time']
 cards.append(f'<figure><div class="pair"><img src="source-{k:02d}.jpg" alt="Source frame at {t:.3f} seconds"><img src="key-{k:02d}.png" alt="Full assembled cartoon key {k}"></div><figcaption>Key {k} · source {t:.3f} s · frame {f}</figcaption></figure>')
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Fan · assembled review · Secondhand Motion</title><link rel="icon" href="../../../favicon.svg"><style>
*{box-sizing:border-box}body{margin:0;background:#f5f1e8;color:#171512;font:17px/1.5 system-ui,sans-serif}.wrap{max-width:1080px;margin:auto;padding:20px}a{color:inherit}h1{font-size:clamp(32px,7vw,62px);line-height:1;margin:22px 0 12px}nav{display:flex;gap:20px;flex-wrap:wrap;font-size:14px}.meta{font-size:14px;color:#625b50}.badge{display:inline-block;background:#ef9f3a;padding:4px 9px;font-size:12px;letter-spacing:.04em;font-weight:700}.player{background:#fffdf7;border:1px solid #d5caba;border-radius:8px;overflow:hidden}video{display:block;width:100%;max-height:65vh;background:#fffdf7}.tabs{display:flex;gap:8px;flex-wrap:wrap;margin:14px 0}button{font:inherit;border:1px solid #aaa18f;background:#fffdf7;color:#171512;border-radius:5px;padding:9px 14px;cursor:pointer}button[aria-pressed=true]{background:#171512;color:#fffdf7}.keys{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}figure{margin:0;border:1px solid #d5caba;background:#fffdf7;border-radius:6px;overflow:hidden}.pair{display:grid;grid-template-columns:repeat(2,minmax(0,1fr))}.pair img{width:100%;display:block}figcaption{padding:10px;font-size:13px}summary{cursor:pointer}details{margin:22px 0}footer{margin:28px 0;border-top:1px solid #d5caba;padding-top:16px;font-size:14px}@media(max-width:600px){.keys{grid-template-columns:1fr}.wrap{padding:14px}button{font-size:15px}}
</style><body><main class="wrap"><nav><a href="../../../index.html">Secondhand Motion</a><a href="../../wave2-keyframes.html">All ten subjects</a><a href="../index.html">Earlier isolated keys</a></nav><h1>Fan in its room.</h1><p class="meta">75 rendered frames · 24 fps · six full-scene keys · 3.125 seconds</p><p><span class="badge">ASSEMBLED REVIEW COPY</span></p><div class="player"><video id="film" controls playsinline preload="metadata" poster="poster.png" src="cartoon.mp4"></video></div><div class="tabs" aria-label="View"><button data-src="cartoon.mp4" data-poster="poster.png" aria-pressed="true">Cartoon</button><button data-src="comparison.mp4" data-poster="comparison-poster.jpg" aria-pressed="false">Source beside cartoon</button><button data-src="source-excerpt.mp4" data-poster="source-01.jpg" aria-pressed="false">Source</button></div><p class="meta">The room and stand hold. The fan head turns slowly on the stand while its rotor spins behind the cage. Rotor phase is authored because the footage does not establish exact RPM. Final playback review is pending.</p><h2>Six moments, fully assembled.</h2><p class="meta">Each pair shows the source at left and its assembled cartoon frame at right.</p><section class="keys">'''+''.join(cards)+'''</section><details><summary>References and review</summary><p>Quick, Draw! key 6400405267283968. Quick, Draw! contributors / Google Creative Lab, CC BY 4.0. Original vectors drive the fan, with separate fixed and rotating parts. Background drawn once by agent against the source frame.</p><p>Archive: <a href="https://www.movingimagearchive.com/sources/we-use-power-b101b72c?clip=7c81549f-fdbe-5064-b148-a63e586f6404">We Use Power (1956)</a>, clip-relative 1.2–4.3043 s. Archive rights were not provided in the candidate manifest.</p><p><a href="shot.json">Timeline and source anchors</a> · <a href="assembly-checks.json">Assembly checks</a> · <a href="review-v2.json">Independent review</a> · <a href="design.png">Integrated revision’s original doodle</a></p><p>Manual source-frame anchors and source crossbar tracking are used. Numeric source registration, SAM and recognition are unrun. No training ran. This review copy is not a release-approved result.</p></details><footer><a href="cartoon.mp4" download>Download cartoon</a> · <a href="comparison.mp4" download>Download synchronized comparison</a></footer></main><script>
const v=document.querySelector('#film');for(const b of document.querySelectorAll('button[data-src]'))b.addEventListener('click',()=>{const t=v.currentTime;const playing=!v.paused;for(const x of document.querySelectorAll('button[data-src]'))x.setAttribute('aria-pressed',String(x===b));v.pause();v.poster=b.dataset.poster;v.src=b.dataset.src;v.addEventListener('loadedmetadata',()=>{v.currentTime=Math.min(t,v.duration||0);if(playing)v.play().catch(()=>{})},{once:true});v.load()});
</script></html>'''
(D/'index.html').write_text(page)
print(D/'index.html')

